 81	public class ShippingCalculator {
 82	    private final TransLogClient transLogClient;
 83	
 84	    public ShippingCalculator(TransLogClient transLogClient) {
 85	        this.transLogClient = transLogClient;
 86	    }
 87	
 88	    public ShippingResult calculate(CheckoutRequest request, Map<String, Product> productMap) {
 89	        BigDecimal totalWeight = calculateTotalWeight(request.getItems(), productMap);
 90	
 91	        return switch (request.getShippingMethod()) {
 92	            case STORE_PICKUP -> new ShippingResult(BigDecimal.ZERO, 1);
 93	            case COURIER -> {
 94	                if (totalWeight.compareTo(new BigDecimal("5.0")) > 0) {
 95	                    throw new ApiException("SHIPPING_METHOD_UNAVAILABLE", 422);
 96	                }
 97	                yield new ShippingResult(new BigDecimal("18.00"), 0);
 98	            }
 99	            case ECONOMY, EXPRESS -> {
100	                try {
101	                    ShippingResult result = transLogClient.quote(
102	                        request.getZipCode(),
103	                        totalWeight,
104	                        request.getShippingMethod(),
105	                        request.getRegion()
106	                    );
107	                    if (result == null) {
108	                        throw new ApiException("SHIPPING_METHOD_UNAVAILABLE", 422);
109	                    }
110	                    yield result;
111	                } catch (RuntimeException e) {
112	                    if (e.getMessage().equals("CARRIER_UNAVAILABLE")) {
113	                        throw new ApiException("CARRIER_UNAVAILABLE", 503);
114	                    }
115	                    throw e;
116	                }
117	            }
118	        };
119	    }
120	
121	    private BigDecimal calculateTotalWeight(List<OrderItem> items, Map<String, Product> productMap) {
122	        BigDecimal total = BigDecimal.ZERO;
123	        for (OrderItem item : items) {
124	            Product product = productMap.get(item.getSku());
125	            total = total.add(product.getWeightKg().multiply(new BigDecimal(item.getQuantity())));
126	        }
127	        return total;
128	    }
129	}
